contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable {
        uint balBefore = address(c).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;

        // The owner can withdraw any value up to the contract's balance,
        // unless value is so large that the transfer itself reverts (e.g. amount exceeds uint96).
        // General rule: if the call succeeds then the contract paid exactly `value`;
        // if it reverts then the contract balance is unchanged or the requested value is extreme.
        assert(
            (reverted && (balAfter == balBefore || value > uint256(type(uint96).max))) ||
            (!reverted && balAfter == balBefore - value)
        );
    }

    receive() external payable {}
}

